    ('樽前山', null, '北海道', null, 42.6905477, 141.376636, 'B', '自然', '樽前山（たるまえさん、たるまえざん、たるまいさん、たるまいざん）は、北海道の道央地方南部にある支笏湖の南側、苫小牧市の北西部に位置する活火山。'),
    ('焼尻島', null, '北海道', null, 44.4343158, 141.4080818, 'B', '自然', '焼尻島（やぎしりとう）は、北海道留萌振興局管内の苫前郡羽幌町の西25kmの日本海に浮かぶ島。'),
    ('納沙布岬', null, '北海道', '根室市', 43.385295, 145.8168199, 'B', '自然', '納沙布岬（のさっぷみさき）は、北海道根室市にある岬。'),
    ('ルスツリゾート', null, '北海道', '留寿都村', 42.7518947, 140.909746, 'B', 'その他', 'ルスツリゾート（英：RUSUTSU RESORT）は、北海道虻田郡留寿都村（ゴルフ場コースの一部は喜茂別町）にあるリゾート施設。'),
    ('襟裳岬', null, '北海道', 'えりも町', 41.924433, 143.249361, 'B', '自然', '襟裳岬（えりもみさき）は、北海道幌泉郡えりも町にある岬である。'),
    ('のぼりべつクマ牧場', null, '北海道', '登別市', 42.4901448, 141.159001, 'B', 'その他', 'のぼりべつクマ牧場（のぼりべつくまぼくじょう）は、北海道登別市登別温泉町にあるクマを主に取り扱う動物園。'),
    ('トラピスト修道院', null, '北海道', '北斗市', 41.7405902, 140.5686226, 'B', 'その他', 'トラピスト修道院（トラピストしゅうどういん）は、カトリックの修道会の一つである厳律シトー会（トラピスト会）の修道院で、日本では主に北海道北斗市三ツ石（渡島当別）に所在する灯台の聖母トラピスト大修道院（とうだいのせいぼトラピストだいしゅうどういん）の通称となっている。'),
    ('青い池', null, '北海道', '美瑛町', 43.4936113, 142.6143394, 'B', 'その他', '青い池（あおいいけ）は、北海道上川郡美瑛町白金にある人造池の通称である。'),
    ('真駒内屋内競技場', null, '北海道', '札幌市', 42.9993975, 141.3473833, 'B', 'その他', '真駒内屋内競技場（まこまないおくないきょうぎじょう）は、北海道札幌市南区の北海道立真駒内公園内にある多目的施設。'),
    ('糠平駅', null, '北海道', '上士幌町', 43.3654972, 143.1984, 'B', 'その他', '糠平駅（ぬかびらえき）は、かつて北海道河東郡上士幌町字糠平に置かれていた、日本国有鉄道（国鉄）士幌線の駅である。'),
    ('倶多楽湖', null, '北海道', '白老町', 42.5101449, 141.185295, 'B', 'その他', '倶多楽湖（クッタラこ、クッタラ湖）は、北海道白老郡白老町にあるカルデラ湖で、活火山「倶多楽」の一部である。'),
    ('カナディアンワールド', null, '北海道', '芦別市', 43.568016, 142.2345881, 'B', 'その他', 'カナディアンワールド（カナディアンワールド）は、北海道芦別市にある民営公園である。'),
    ('然別湖', null, '北海道', null, 43.2976768, 143.1159748, 'B', '自然', '然別湖（しかりべつこ）は、北海道十勝管内の鹿追町北部と上士幌町南西部にまたがる湖である。'),
    ('幸福駅', null, '北海道', null, 42.743721, 143.16152, 'B', 'その他', '幸福駅（こうふくえき）は、北海道（十勝支庁）帯広市幸福町にあった日本国有鉄道（国鉄）広尾線の駅である。'),
    ('十勝スピードウェイ', null, '北海道', '更別村', 42.63006, 143.2903561, 'B', 'その他', '十勝スピードウェイ（TOKACHI SPEEDWAY）は、北海道河西郡更別村にあるサーキット。'),
    ('鰊御殿', null, '北海道', null, 43.2378219, 141.0157328, 'B', 'その他', '鰊御殿（にしんごてん）は、一般的には、第二次世界大戦前に北海道の日本海側に建てられた、網元や漁師たちが寝泊りした居宅兼漁業施設（番屋）の俗称。'),
    ('オンネトー', null, '北海道', '足寄町', 43.3817944, 143.9681385, 'B', '自然', 'オンネトーは、北海道足寄郡足寄町東部の阿寒摩周国立公園内にある湖である。'),
    ('ニセコアンヌプリ', null, '北海道', null, 42.8749957, 140.6588448, 'B', '自然', 'ニセコアンヌプリは、北海道後志総合振興局かつニセコ積丹小樽海岸国定公園内にある標高1,308.2メートルの火山。'),
    ('小樽市総合博物館', null, '北海道', '小樽市', 43.2108261, 141.0002718, 'B', '美術館博物館', '小樽市総合博物館（おたるしそうごうはくぶつかん）は、北海道小樽市手宮1丁目にある北海道の歴史や自然、鉄道をはじめとした交通、科学などに関する展示を行う博物館である。'),
    ('中島公園', null, '北海道', '札幌市', 43.044502, 141.354139, 'B', 'その他', '中島公園（なかじまこうえん）は、北海道札幌市中央区にある公園。'),
    ('定山渓温泉', null, '北海道', '札幌市', 42.9700425, 141.1664361, 'B', 'その他', '定山渓温泉（じょうざんけい おんせん）は、北海道札幌市南区にある温泉地。'),
    ('帯広競馬場', null, '北海道', '帯広市', 42.9230497, 143.1823181, 'B', 'その他', '帯広競馬場（おびひろけいばじょう Obihiro Racecourse）は、北海道帯広市にあるばんえい競馬の競馬場である。'),
    ('アトサヌプリ', null, '北海道', '弟子屈町', 43.6104074, 144.4386401, 'B', '自然', 'アトサヌプリ（アイヌ語ラテン文字表記: atusa-nupuri）は、北海道弟子屈町にある第四紀火山である。'),
    ('雌阿寒岳', null, '北海道', null, 43.3863191, 144.0087915, 'B', 'その他', '雌阿寒岳（めあかんだけ）は、北海道東部にある阿寒カルデラの南西部にある8つの火山で構成される成層火山群の総称。'),
    ('札幌市円山動物園', null, '北海道', '札幌市', 43.0493632, 141.3066944, 'B', 'その他', '札幌市円山動物園（さっぽろしまるやまどうぶつえん）は、北海道札幌市中央区宮ケ丘の円山公園内にある動物園。'),
    ('夕張市石炭博物館', null, '北海道', '夕張市', 43.0683537, 141.9890699, 'B', '美術館博物館', '夕張市石炭博物館（ゆうばりしせきたんはくぶつかん）は、北海道夕張市高松7-1にある博物館。'),
    ('風蓮湖', null, '北海道', '根室市', 43.3084869, 145.3223521, 'B', '自然', '風蓮湖（ふうれんこ）は、北海道根室市、野付郡別海町にまたがる湖。'),
    ('三笠鉄道記念館', null, '北海道', '三笠市', 43.2273617, 141.9039856, 'B', '美術館博物館', '三笠鉄道記念館（みかさてつどうきねんかん）は、北海道三笠市にある鉄道を中心とした博物館。'),
    ('野寒布岬', null, '北海道', '稚内市', 45.449827, 141.6453404, 'B', '自然', '野寒布岬（のしゃっぷみさき）は、北海道稚内市ノシャップにある岬である。'),
    ('羅臼岳', null, '北海道', null, 44.0759225, 145.1222288, 'B', '自然', '羅臼岳（らうすだけ）は、北海道・知床半島にある火山群の主峰および最高峰で標高1,661メートル。'),
    ('手稲山', null, '北海道', '札幌市', 43.0766117, 141.1931943, 'B', '自然', '手稲山（ていねやま）は、北海道札幌市西部の手稲区と西区に跨る標高1023.1mの山。'),
    ('碧血碑', null, '北海道', '函館市', 41.7515146, 140.7088637, 'B', 'その他', '碧血碑（へきけつひ、へっけつひ）は、北海道函館市、函館山の麓に明治8年（1875年）9月に建立された戊辰戦争、特に箱館戦争における旧幕府軍の戦死者を記念する慰霊碑。'),
    ('トラピスチヌ修道院', null, '北海道', '函館市', 41.7877395, 140.8227326, 'B', 'その他', '天使の聖母トラピスチヌ修道院（てんしのせいぼトラピスチヌしゅうどういん）は、北海道函館市郊外にあるトラピスト会（厳律シトー会）系の女子修道院である。'),
    ('ニセコ', null, '北海道', null, 42.8401484, 140.6330037, 'B', 'その他', 'ニセコ（英: Niseko）は、広義には、北海道後志総合振興局の岩内郡岩内町、岩内郡共和町、虻田郡倶知安町、虻田郡ニセコ町、磯谷郡蘭越町からなる山岳丘陵地域の総称。'),
    ('アポイ岳', null, '北海道', '様似町', 42.1078829, 143.0256734, 'B', '自然', 'アポイ岳（アポイだけ）は、北海道様似郡様似町にある標高810.5 mの山である。'),
    ('キロロリゾート', null, '北海道', '赤井川村', 43.0673599, 140.9903512, 'B', 'その他', 'キロロリゾート（英: Kiroro Resort）は、北海道余市郡赤井川村にあるリゾート施設。'),
    ('おたる水族館', null, '北海道', '小樽市', 43.2373315, 141.0124695, 'B', '美術館博物館', 'おたる水族館（おたるすいぞくかん英：OTARU AQUARIUM）は、小樽水族館公社が北海道小樽市で運営する水族館。'),
    ('糠平ダム', null, '北海道', null, 43.3947466, 143.2042317, 'B', 'その他', '糠平ダム（ぬかびらダム）は、北海道十勝総合振興局河東郡上士幌町にある十勝川水系一級河川音更川中流部に築造されたダム。'),
    ('クッチャロ湖', null, '北海道', null, 45.1335957, 142.3110607, 'B', '自然', 'クッチャロ湖（クッチャロこ）は、北海道北部、宗谷総合振興局管内枝幸郡浜頓別町に存在する周囲約27 kmの汽水湖である。'),
    ('知床岬', null, '北海道', null, 44.3450893, 145.3297798, 'B', '自然', '知床岬（しれとこみさき）は、北海道北東部、斜里郡斜里町遠音別村岩尾別にある岬。'),
    ('幌尻岳', null, '北海道', '平取町', 42.7199833, 142.6827333, 'B', '自然', '幌尻岳（ぽろしりだけ）は、北海道日高振興局の沙流郡平取町と新冠郡新冠町にまたがる標高2,052 mの山。'),
    ('豊富温泉', null, '北海道', '豊富町', 45.075775, 141.8386675, 'B', '温泉', '豊富温泉（とよとみおんせん）は、北海道天塩郡豊富町にある温泉。'),
    ('チキウ岬', null, '北海道', '室蘭市', 42.3012856, 141.0022312, 'B', '自然', 'チキウ岬（チキウみさき）は、北海道室蘭市の太平洋に面する岬である。'),
    ('トドワラ', null, '北海道', null, 43.5813138, 145.3275668, 'B', '自然', 'トドワラは、北海道東部の根室振興局野付郡別海町の野付半島にある、立ち枯れたトドマツ林の跡である。'),
    ('ウトナイ湖', null, '北海道', '苫小牧市', 42.7065132, 141.7212192, 'B', '自然', 'ウトナイ湖（ウトナイこ）は、北海道苫小牧市の東部にある淡水湖。'),
    ('金森赤レンガ倉庫', null, '北海道', '函館市', 41.7661843, 140.7164492, 'B', 'その他', '金森赤レンガ倉庫（かねもりあかレンガそうこ、英文表記:Kanemori Red Brick Warehouse）は、北海道函館市にある赤レンガ倉庫群の名称。'),
    ('さっぽろ羊ヶ丘展望台', null, '北海道', '札幌市', 42.9989435, 141.3944382, 'B', 'その他', 'さっぽろ羊ヶ丘展望台（さっぽろひつじがおかてんぼうだい、略称: 「羊ヶ丘展望台」、英: "Hitsujigaoka Observation Hill"）は、北海道札幌市豊平区羊ケ丘にある北海道内でも屈指の観光名所である。'),
    ('登別マリンパークニクス', null, '北海道', '登別市', 42.455571, 141.1825958, 'B', '美術館博物館', '登別マリンパークニクス（のぼりべつマリンパークニクス）は、北海道登別市に所在する日本の水族館。'),
    ('ファーム富田', null, '北海道', '中富良野町', 43.41796, 142.427787, 'B', 'その他', 'ファーム富田（ファームとみた）は、北海道空知郡中富良野町にある農園。'),
    ('能取湖', null, '北海道', '網走市', 44.0786786, 144.1707967, 'B', '自然', '能取湖（のとろこ、のとりこ）は、北海道網走市にある湖。'),
    ('立待岬', null, '北海道', '函館市', 41.7450217, 140.7216193, 'B', '自然', '立待岬（たちまちみさき）は、北海道函館市住吉町にある、津軽海峡に面した岬である。'),
    ('釧路フィッシャーマンズワーフMOO', null, '北海道', '釧路市', 42.9818239, 144.3836854, 'B', 'その他', '釧路フィッシャーマンズワーフMOO（くしろフィッシャーマンズワーフ・ムー）は、北海道釧路市にある複合商業施設。'),
    ('麓郷の森', null, '北海道', '富良野市', 43.3121973, 142.5404549, 'B', 'その他', '麓郷の森（ろくごうのもり）は、北海道富良野市東麓郷にあるテレビドラマ『北の国から』の初期のロケ地であり、1984年からは新たに観光名所として整備された。'),
    ('神の子池', null, '北海道', null, 43.6453845, 144.5497209, 'B', 'その他', '神の子池（かみのこいけ）は、北海道オホーツク管内斜里郡清里町の森林内にある池である。'),
    ('室蘭港', null, '北海道', '室蘭市', 42.3271991, 140.9765039, 'B', 'その他', '室蘭港（むろらんこう）は、北海道室蘭市にある港湾。'),
    ('網走湖', null, '北海道', '大空町', 43.9782426, 144.2038569, 'B', '自然', '網走湖（あばしりこ）は、北海道網走市と網走郡大空町にまたがる湖である。'),
    ('十勝川温泉', null, '北海道', '音更町', 42.950583, 143.298131, 'B', '温泉', '十勝川温泉（とかちがわおんせん）は、北海道河東郡音更町にある温泉。'),
    ('スコトン岬', null, '北海道', '礼文町', 45.4641538, 140.9672521, 'B', '自然', 'スコトン岬（スコトンみさき）は、北海道礼文郡礼文町にある礼文島の岬。'),
    ('函館ハリストス正教会', null, '北海道', '函館市', 41.7628077, 140.7122466, 'B', 'その他', '函館ハリストス正教会（はこだてハリストスせいきょうかい）は、日本ハリストス正教会に所属し、主の復活聖堂（しゅのふっかつせいどう・北海道函館市元町に所在）を有する、正教会の教会である。'),
    ('釧路川', null, '北海道', null, 43.1950525, 144.4437026, 'B', 'その他', '釧路川（くしろがわ）は、北海道東部を流れ太平洋に注ぐ一級河川。'),
    ('オコタンペ湖', null, '北海道', '千歳市', 42.8038414, 141.2566047, 'B', 'その他', 'オコタンペ湖（オコタンペこ）は、北海道千歳市西部にある小さな湖で、支笏湖の北西7kmほどに位置している。'),
    ('洞爺湖温泉', null, '北海道', '洞爺湖町', 42.563018, 140.836566, 'B', '温泉', '洞爺湖温泉（とうやこおんせん、英: Lake Toya Onsen）は、北海道虻田郡洞爺湖町にある温泉、または洞爺湖町と有珠郡壮瞥町の地名。'),
    ('北海道博物館', null, '北海道', null, 43.052234, 141.49706, 'B', 'その他', '北海道博物館（ほっかいどうはくぶつかん、英語: Hokkaido Museum）は、2015年（平成27年）4月18日に開館した総合博物館で、愛称は森のちゃれんがである。'),
    ('道の駅まるせっぷ', null, '北海道', '遠軽町', 43.9959615, 143.3287026, 'B', 'その他', '道の駅まるせっぷ（みちのえき まるせっぷ）は、北海道紋別郡遠軽町にあった国道333号の道の駅である。'),
    ('養老牛温泉', null, '北海道', '中標津町', 43.5883961, 144.7227919, 'B', '温泉', '養老牛温泉（ようろううしおんせん）は、北海道標津郡中標津町にある温泉。'),
    ('沙流川', null, '北海道', null, 42.6287794, 142.146837, 'B', 'その他', '沙流川（さるがわ）は、北海道日高振興局管内を流れ太平洋に注ぐ一級河川。'),
    ('桂沢ダム', null, '北海道', '三笠市', 43.2303714, 142.0309268, 'B', 'その他', '桂沢ダム（かつらざわダム）は、北海道三笠市、一級河川・石狩川水系幾春別川に建設されたダムである。'),
    ('サッポロビール博物館', null, '北海道', '札幌市', 43.0715487, 141.3689183, 'B', '美術館博物館', 'サッポロビール博物館（サッポロビールはくぶつかん）は、北海道札幌市東区にある企業博物館。'),
    ('キタカラ', null, '北海道', '稚内市', 45.4174315, 141.6777028, 'B', 'その他', 'キタカラ（KITAcolor）は、北海道稚内市にある複合施設（駅ビル・バスターミナル・道の駅）。'),
    ('稚内港', null, '北海道', '稚内市', 45.4178675, 141.680716, 'B', 'その他', '稚内港（わっかないこう）は、北海道稚内市にある港湾。'),
    ('月形樺戸博物館', null, '北海道', '月形町', 43.3387648, 141.6692439, 'B', '美術館博物館', '月形樺戸博物館（つきがたかばとはくぶつかん）は、北海道樺戸郡月形町にある月形町立の博物館。'),
    ('宗谷丘陵', null, '北海道', '稚内市', 45.481809, 141.917829, 'B', 'その他', '宗谷丘陵（そうやきゅうりょう）は、北海道稚内市にある日本最北の丘陵。'),
    ('厚岸湖', null, '北海道', '厚岸町', 43.0657101, 144.8519524, 'B', 'その他', '厚岸湖（あっけしこ）は、北海道厚岸郡厚岸町にある湖で厚岸霧多布昆布森国定公園に含まれる。'),
    ('釧路市動物園', null, '北海道', '釧路市', 43.0830411, 144.2347383, 'C', 'その他', '釧路市動物園（くしろしどうぶつえん）は、北海道釧路市阿寒町にある動物園。'),
    ('滝野すずらん丘陵公園', null, '北海道', '札幌市', 42.9177014, 141.384665, 'C', 'その他', '滝野すずらん丘陵公園（たきのすずらんきゅうりょうこうえん）は、北海道札幌市南区にある公園。'),
    ('豊平峡ダム', null, '北海道', null, 42.9154243, 141.1552206, 'C', 'その他', '豊平峡ダム（ほうへいきょうダム）は、札幌市南区定山渓、一級河川・石狩川水系豊平川の上流部に建設されたダムである。'),
    ('モヨロ貝塚', null, '北海道', '網走市', 44.0251551, 144.2677889, 'C', 'その他', 'モヨロ貝塚（モヨロかいづか）は、北海道網走市北1条から北3条東2丁目にかけてあるオホーツク文化の代表的遺跡である。'),
    ('キウス周堤墓群', null, '北海道', '千歳市', 42.8842054, 141.7157441, 'C', 'その他', 'キウス周堤墓群（キウスしゅうていぼぐん）は、北海道千歳市にある縄文後期の集団墓8基で構成される史跡。'),
    ('春国岱', null, '北海道', '根室市', 43.278391, 145.43728, 'C', 'その他', '春国岱（しゅんくにたい）は、北海道根室市春国岱にある風蓮湖と根室湾を分ける砂州で形成された面積約600haの湿地及び原生林。'),
    ('北きつね牧場', null, '北海道', '北見市', 43.755611, 143.497072, 'C', 'その他', '北きつね牧場（きたきつねぼくじょう）は、北海道北見市留辺蘂町（旧：常呂郡留辺蘂町）花丘地区にあるキツネ専門の動物園。'),
    ('谷地頭温泉', null, '北海道', '函館市', 41.7516957, 140.7142234, 'C', '温泉', '谷地頭温泉（やちがしらおんせん）は、北海道函館市谷地頭町にある温泉。'),
    ('山の水族館', null, '北海道', '北見市', 43.7547567, 143.5007404, 'C', '美術館博物館', '山の水族館（やまのすいぞくかん　YAMA NO Aquarium）は北海道北見市留辺蘂町（るべしべちょう）の温根湯温泉（おんねゆおんせん）にある淡水魚の水族館。'),
    ('金山ダム', null, '北海道', '南富良野町', 43.1542845, 142.4891406, 'C', 'その他', '金山ダム（かなやまダム）は、北海道空知郡南富良野町、一級河川・石狩川水系空知川最上流部に建設されたダムである。'),
    ('知床峠', null, '北海道', '羅臼町', 44.0543176, 145.1051452, 'C', '自然', '知床峠（しれとことうげ）は、北海道目梨郡羅臼町と斜里郡斜里町の境にある国道334号の峠。'),
    ('濤沸湖', null, '北海道', null, 43.934838, 144.3941538, 'C', '自然', '濤沸湖（とうふつこ）は、北海道北東部、網走市と小清水町にまたがる汽水湖。'),
    ('久種湖', null, '北海道', null, 45.4325556, 141.0395395, 'C', '自然', '久種湖（くしゅこ）は、北海道北部、宗谷総合振興局管内礼文郡礼文町にある淡水湖である。'),
    ('洞爺湖有珠山ジオパーク', null, '北海道', null, 42.5593869, 140.8988039, 'C', 'その他', '洞爺湖有珠山ジオパーク（とうやこうすざんジオパーク、英: Toya Caldera and Usu Volcano Global Geopark）は、北海道にある洞爺湖及び有珠山を中心とし、伊達市、豊浦町、壮瞥町、洞爺湖町にひろがるジオパークである。'),
    ('横綱千代の山・千代の富士記念館', null, '北海道', '福島町', 41.4791179, 140.2556351, 'C', '美術館博物館', '横綱千代の山・千代の富士記念館（よこづなちよのやま ちよのふじきねんかん）は、北海道松前郡福島町字福島190番地にある福島町立の千代の山雅信と千代の富士貢の記念館である。'),
    ('水無海浜温泉', null, '北海道', '函館市', 41.8111255, 141.1843086, 'C', '温泉', '水無海浜温泉（みずなしかいひんおんせん）は、北海道函館市椴法華地区にある温泉である。'),
    ('チミケップ湖', null, '北海道', null, 43.6460039, 143.8659676, 'C', '自然', 'チミケップ湖（チミケップこ）は、北海道東部、オホーツク管内網走郡津別町字沼沢にある湖である。'),
    ('天塩川温泉', null, '北海道', '音威子府村', 44.6605283, 142.2545661, 'C', '温泉', '天塩川温泉（てしおがわおんせん）は、北海道中川郡音威子府村咲来にある温泉。'),
    ('美幌峠', null, '北海道', '美幌町', 43.645449, 144.2486516, 'C', '自然', '美幌峠（びほろとうげ）は、北海道網走郡美幌町と川上郡弟子屈町の境にある国道243号の峠。'),
    ('雌阿寒温泉', null, '北海道', '足寄町', 43.3946435, 143.9840889, 'C', 'その他', '雌阿寒温泉（めあかんおんせん）は、北海道足寄郡足寄町にある温泉（硫黄泉）である。'),
    ('パンケ沼', null, '北海道', '幌延町', 45.0403851, 141.7245506, 'C', '自然', 'パンケ沼（パンケぬま、パンケトウ）は、北海道幌延町字下沼、サロベツ原野に位置する円形の塩沼（汽水湖）。'),
    ('おびひろ動物園', null, '北海道', '帯広市', 42.9009489, 143.184655, 'C', 'その他', 'おびひろ動物園（おびひろどうぶつえん）は、北海道帯広市にある動物園。'),
    ('塘路湖', null, '北海道', null, 43.1521586, 144.5117223, 'C', '自然', '塘路湖（とうろこ）は、北海道東部、標茶町にある淡水湖。'),
